args.query:
\d+ api.*
select n.nspname, c.relname, c.relkind, c.relrowsecurity, c.relforcerowsecurity, pg_get_userbyid(c.relowner) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('api','public') and c.relkind in ('r','v','m');
select * from pg_policies;
select tgname, tgrelid::regclass, pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select proname, pronamespace::regnamespace, prosecdef from pg_proc where pronamespace::regnamespace::text in ('api','public');

select grantee, table_name, privilege_type, column_name from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC') and table_name='application' order by 1,3,4;
select grantee, table_name, string_agg(privilege_type,',') from information_schema.table_privileges where table_schema='api' and grantee not in ('postgres') group by 1,2 order by 2,1;
select p.proname, pg_get_functiondef(p.oid) from pg_proc p where pronamespace::regnamespace::text in ('priv') ;

alter table api.application add column internal_score numeric;
grant update (internal_score) on api.application to expert;
grant select (internal_score), insert (internal_score), update (internal_score) on api.application to fund_admin;
revoke all (internal_score) on api.application from applicant, public;
notify pgrst, 'reload schema';
select grantee, privilege_type from information_schema.column_privileges where table_name='application' and column_name='internal_score';
